-- tests/fixtures/bay_release_stub.sql: the bay release as live, and everything it calls, for
-- tests/test_bay_release_reads_the_work_sql.py (db/migrations/0757). Loaded after tests/fixtures/agent_charge_order_stub.sql
-- (vehicles, stalls, bookings, visits, runs, the policy reader) and tests/fixtures/bay_activation_stub.sql (the activation the
-- release calls, the reserve, the two vehicle triggers, the legs and sweep tables). Read from the live catalog on 2026-10-18
-- between 4:31 and 4:45 AM CT (the test asserts each md5 of prosrc):
--   ottoq.ottoq_release_vacated_spaces ec00f541, public.ottoq_reopen_visit_atoms 36b5c7b5,
--   ottoq.ottoq_emit_booking_interrupted 445b0093, ottoq.ottoq_booking_interrupted aa7c9cce, ottoq.ottoq_is_bay_purpose
--   a5115860, ottoq.ottoq_occupancy_cut_short bebe8c24, ottoq.ottoq_bay_purpose_atoms 84bc5c36,
--   ottoq.ottoq_bay_purpose_leg_types a85ac638, and the sweep cells' trigger, public.ottoq_throughput_sweep_cells_control
--   acaab7a0;
-- the live columns the release reads beyond those stubs (a leg's planned_duration_s and duration_basis, an event's), the
-- live default of a booking's booked_at, and the live index of the events by car. The rows 0746 and 0747 write that 0757's
-- P1 reads: their lineage, and the sweeps robowash_normal_2026_10_18 (4 cells) and uptimefirst_busy_2026_10_18 (2), with no
-- arm. Three stand-ins, noted where defined: the departed-space release (inert on live at its default), the event writer
-- (the live signature, recording each call), and the service flow, which carries, byte for byte, the three passages of its
-- STEP 1 that 0757's P1 reads and is never called: the tests write what STEP 1 leaves behind (the car out of its bay, the
-- bay's atoms done, its twin.service_completed) as rows.
SET client_min_messages = warning;

-- live columns of a leg the release's re-plan writes
ALTER TABLE public.ottoq_itinerary_legs ADD COLUMN IF NOT EXISTS planned_duration_s integer,
                                        ADD COLUMN IF NOT EXISTS duration_basis jsonb;
-- live: a booking is stamped when it is made
ALTER TABLE public.ottoq_stall_bookings ALTER COLUMN booked_at SET DEFAULT now();

-- live: the events, with the columns 0757 reads, and their index by car
CREATE TABLE IF NOT EXISTS public.ottoq_events (event_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_seq bigserial,
  occurred_at timestamptz DEFAULT now(), event_type text, entity_type text, entity_id uuid, depot_id uuid,
  payload jsonb, data_source text, sim_run_id uuid, sim_clock_at timestamptz);
CREATE INDEX IF NOT EXISTS ottoq_events_keep_entity_type_entity_id_occurred_at_idx
  ON public.ottoq_events USING btree (entity_type, entity_id, occurred_at DESC);

CREATE TABLE IF NOT EXISTS public.ottoq_throughput_sweep_arms (
  arm_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, sweep_id uuid, cell_id uuid, seed bigint,
  replicate boolean DEFAULT false, sim_run_id uuid, ran_at timestamptz DEFAULT now(), complete boolean, wall_s numeric);

-- STAND-IN: the event writer, with the live signature (pg_get_function_arguments), recording each call as
-- tests/fixtures/bay_activation_stub.sql's does, the depot included
DROP FUNCTION IF EXISTS public.ottoq_record_event(text, text, text, text, uuid, jsonb, text, text, text, uuid);
ALTER TABLE public.test_bay_events ADD COLUMN IF NOT EXISTS depot_id uuid;
CREATE OR REPLACE FUNCTION public.ottoq_record_event(p_actor_type text, p_event_type text, p_entity_type text,
  p_entity_id uuid DEFAULT NULL::uuid, p_payload jsonb DEFAULT '{}'::jsonb, p_actor_id text DEFAULT NULL::text,
  p_actor_metadata jsonb DEFAULT '{}'::jsonb, p_fleet_operator_id uuid DEFAULT NULL::uuid, p_depot_id uuid DEFAULT NULL::uuid,
  p_previous_state jsonb DEFAULT NULL::jsonb, p_new_state jsonb DEFAULT NULL::jsonb, p_severity text DEFAULT NULL::text,
  p_correlation_id uuid DEFAULT NULL::uuid, p_parent_event_id uuid DEFAULT NULL::uuid, p_related_task_id uuid DEFAULT NULL::uuid,
  p_related_schedule_id uuid DEFAULT NULL::uuid, p_related_decision_id uuid DEFAULT NULL::uuid, p_outcome text DEFAULT NULL::text,
  p_latency_ms integer DEFAULT NULL::integer, p_ingest_source text DEFAULT 'app'::text,
  p_signing_key_id text DEFAULT 'system:v1'::text, p_data_source text DEFAULT 'production'::text,
  p_sim_run_id uuid DEFAULT NULL::uuid)
 RETURNS uuid LANGUAGE plpgsql
AS $function$
BEGIN
  INSERT INTO public.test_bay_events (event_type, entity_id, payload, severity, sim_run_id, depot_id)
  VALUES (p_event_type, p_entity_id, p_payload, p_severity, p_sim_run_id, p_depot_id);
  RETURN gen_random_uuid();
END $function$;

-- STAND-IN: the departed-space release (0329), inert on live unless space_departure_release_enabled = 1
CREATE OR REPLACE FUNCTION ottoq.ottoq_release_departed_spaces(p_sim_run_id uuid, p_depot_id uuid, p_clock timestamp with time zone)
 RETURNS integer LANGUAGE sql
AS $function$ SELECT 0 $function$;

-- STAND-IN: the service flow, never called. Its body carries, byte for byte, the three passages of the live STEP 1 that
-- 0757's P1 reads (the bay's capability sets, and the event it emits as a car leaves its bay with its work credited).
CREATE OR REPLACE FUNCTION twin.ottoq_sim_advance_service_flow(p_sim_run_id uuid, p_sim_clock_now timestamp with time zone,
                                                              p_dt_minutes numeric, p_depot_id uuid)
 RETURNS integer LANGUAGE plpgsql
AS $function$
BEGIN
  RAISE EXCEPTION 'stand-in: the service flow is not executed in this world';
  /* the live STEP 1, as 0757 reads it:
    v_bay_caps := CASE WHEN v_rec.current_state = 'in_wash_bay' THEN ARRAY['exterior_wash','sensor_clean']
                       WHEN v_rec.current_state = 'in_detail_bay' THEN ARRAY['interior_deep_clean','exterior_wash','interior_tidy']
                       ELSE ARRAY['mechanical_pm','sensor_calibration','fault_repair','cosmetic_repair'] END;
    PERFORM ottoq_record_event(p_actor_type := 'av_vehicle', p_actor_id := v_rec.id::text, p_event_type := 'twin.service_completed',
      p_entity_type := 'vehicle', p_entity_id := v_rec.id, p_payload := jsonb_build_object('from', v_rec.current_state, 'self_healed', (v_rec.config->>'service_ends_at') IS NULL,
        'bay_capable', to_jsonb(v_bay_caps), 'credited', to_jsonb(v_credit),
  */
END $function$;

-- live: the sweep cells' contrast trigger
CREATE OR REPLACE FUNCTION public.ottoq_throughput_sweep_cells_control()
 RETURNS trigger LANGUAGE plpgsql
AS $function$
DECLARE
  k public.ottoq_throughput_sweep_cells%ROWTYPE;
BEGIN
  IF NEW.control_cell_code IS NULL THEN
    RETURN NEW;                     -- not a treatment: nothing to check
  END IF;
  SELECT * INTO k FROM public.ottoq_throughput_sweep_cells
   WHERE sweep_id = NEW.sweep_id AND cell_code = NEW.control_cell_code;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'sweep cell %: control % is not a cell of the same sweep', NEW.cell_code, NEW.control_cell_code;
  END IF;
  IF k.seat <> NEW.seat OR k.buildout_code <> NEW.buildout_code THEN
    RAISE EXCEPTION 'sweep cell %: a contrast differs only by its dials, but control % is seat % on %, not seat % on %',
      NEW.cell_code, k.cell_code, k.seat, k.buildout_code, NEW.seat, NEW.buildout_code;
  END IF;
  IF k.control_cell_code IS NOT NULL THEN
    RAISE EXCEPTION 'sweep cell %: control % is itself a treatment', NEW.cell_code, k.cell_code;
  END IF;
  IF k.fixed_params = NEW.fixed_params THEN
    RAISE EXCEPTION 'sweep cell %: it has the same dials as its control %, so there is nothing to contrast', NEW.cell_code, k.cell_code;
  END IF;
  IF EXISTS (SELECT 1 FROM public.ottoq_throughput_sweep_cells c
              WHERE c.sweep_id = NEW.sweep_id AND c.control_cell_code = NEW.cell_code) THEN
    RAISE EXCEPTION 'sweep cell %: it is another cell''s control, so it cannot be a treatment', NEW.cell_code;
  END IF;
  RETURN NEW;
END $function$;
CREATE TRIGGER trg_ottoq_throughput_sweep_cells_control BEFORE INSERT OR UPDATE ON public.ottoq_throughput_sweep_cells
  FOR EACH ROW EXECUTE FUNCTION ottoq_throughput_sweep_cells_control();

