-- the live bodies (pg_get_functiondef, prosrc byte for byte)

CREATE OR REPLACE FUNCTION ottoq.ottoq_is_bay_purpose(p_purpose text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
AS $function$
  -- The purposes whose completion is defined by TIME IN THE BAY.
  -- Charging is deliberately EXCLUDED: a charge that ends early ended because the vehicle
  -- reached target SoC -- that is a COMPLETE charge, not an interruption. Charge
  -- completeness is an SoC question, not a duration question.
  -- staging / temp_hold / perimeter_hold are parking, not work.
  SELECT COALESCE(p_purpose,'') = ANY (ARRAY['wash','detail','service','inspect']);
$function$;

CREATE OR REPLACE FUNCTION ottoq.ottoq_occupancy_cut_short(p_planned_s numeric, p_actual_s numeric)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- The rule, verbatim from ottoq_booking_interrupted's BUILD 2 calibration on
  -- run 6b22906b (busy_day/424242): actual < 80% of planned AND shortfall >=
  -- 120 s. The 80% sits inside the widest gap in that run's bimodal completion
  -- distribution (17 rows <= 0.630, 7 rows >= 0.828), so the split is a
  -- structural break and not a tuned knob; the 120 s floor is a guard rail for
  -- short bays and was inert on the calibration run. NOT retuned here — this
  -- function exists so the constants live in exactly one place now that a
  -- non-bay caller needs them too.
  SELECT p_planned_s IS NOT NULL AND p_planned_s > 0
     AND p_actual_s  IS NOT NULL
     AND p_actual_s < 0.80 * p_planned_s
     AND (p_planned_s - p_actual_s) >= 120;
$function$;

CREATE OR REPLACE FUNCTION ottoq.ottoq_booking_interrupted(p_purpose text, p_planned_s numeric, p_actual_s numeric)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- 0329: unchanged in behaviour — the bay gate over the shared rule. E1 in
  -- the migration proves this composition equals the previous inline body on a
  -- 200-row grid including the NULL and zero edges.
  SELECT ottoq.ottoq_is_bay_purpose(p_purpose)
     AND ottoq.ottoq_occupancy_cut_short(p_planned_s, p_actual_s);
$function$;

CREATE OR REPLACE FUNCTION ottoq.ottoq_bay_purpose_atoms(p_purpose text)
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
AS $function$
  -- MUST MIRROR twin.ottoq_sim_advance_service_flow STEP 1, which is what marks these atoms
  -- done on bay exit. TOTAL: an unknown purpose returns '{}' and re-plans nothing, it never
  -- raises. (Twin vocabulary is OPEN; OTTO-Q's is CLOSED.)
  SELECT CASE COALESCE(p_purpose,'')
    WHEN 'wash'    THEN ARRAY['exterior_wash','sensor_clean']
    WHEN 'detail'  THEN ARRAY['interior_deep_clean','exterior_wash','interior_tidy']
    WHEN 'service' THEN ARRAY['mechanical_pm','sensor_calibration','fault_repair','cosmetic_repair']
    WHEN 'inspect' THEN ARRAY['interior_inspection']
    ELSE '{}'::text[]
  END;
$function$;

CREATE OR REPLACE FUNCTION ottoq.ottoq_bay_purpose_leg_types(p_purpose text)
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
AS $function$
  SELECT CASE COALESCE(p_purpose,'')
    WHEN 'wash'    THEN ARRAY['wash','exterior_wash','sensor_clean']
    WHEN 'detail'  THEN ARRAY['detail','interior_deep_clean','interior_tidy']
    WHEN 'service' THEN ARRAY['service','mechanical_pm','sensor_calibration','fault_repair','cosmetic_repair']
    WHEN 'inspect' THEN ARRAY['inspect','interior_inspection']
    ELSE '{}'::text[]
  END;
$function$;

CREATE OR REPLACE FUNCTION public.ottoq_reopen_visit_atoms(p_vehicle uuid, p_svcs text[], p_since timestamp with time zone, p_reason text, p_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE v_visit uuid; v_atoms jsonb; v_new jsonb := '[]'::jsonb; v_a jsonb;
        v_n int := 0;            -- atoms genuinely RE-OPENED (credit voided / work cut mid-flight)
        v_from_done int := 0;    -- strict phase-9 definition: atom had been marked done
        v_from_active int := 0;  -- atom was visibly mid-work
        v_already_due int := 0;  -- atom matched the service set but was never credited
        v_outstanding int := 0; v_status text; v_st text;
        v_meta jsonb := '{}'::jsonb; v_run uuid;
        v_fallback boolean := false; v_attempts int := 0; v_max int := 3;
        v_stamp jsonb; v_row_reopened boolean := false;
BEGIN
  IF p_vehicle IS NULL THEN RETURN 0; END IF;
  -- TOTAL: an unknown/empty purpose maps to no atoms; nothing to re-open.
  IF p_svcs IS NULL OR array_length(p_svcs,1) IS NULL THEN RETURN 0; END IF;

  -- (1) The LIVE visit.
  SELECT vn.visit_id, vn.atoms, vn.status, COALESCE(vn.meta,'{}'::jsonb), vn.sim_run_id
    INTO v_visit, v_atoms, v_status, v_meta, v_run
    FROM ottoq_visit_needs vn
   WHERE vn.vehicle_id = p_vehicle AND vn.status IN ('open','in_progress') AND COALESCE(vn.sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid) = COALESCE((SELECT r0.sim_run_id FROM public.ottoq_sim_runs r0 WHERE r0.status = 'running' AND r0.depot_id = vn.depot_id ORDER BY r0.started_at DESC LIMIT 1), '00000000-0000-0000-0000-000000000000'::uuid) /* 0124 */
   ORDER BY vn.created_at DESC LIMIT 1;

  -- (2) FALLBACK, WIDENED (PHASE 10 FIX B-3).
  -- The old fallback pre-filtered with EXISTS(atom.svc = ANY(p_svcs)). MEASURED (phase 9,
  -- vehicle 2d2c46af): a booking with purpose='wash' -> p_svcs {exterior_wash,sensor_clean}
  -- was matched against a manifest whose only bay atom was 'interior_deep_clean'
  -- (workflow_plan leg 2, requires_bay='detail'). The intersection was EMPTY, the row was
  -- invisible to the fallback, and the outstanding work was forgotten outright.
  -- A needs row that still OWES work now qualifies on its own, intersection or not; the
  -- intersection only decides RANKING.
  IF v_visit IS NULL THEN
    SELECT c.visit_id, c.atoms, c.status, COALESCE(c.meta,'{}'::jsonb), c.sim_run_id
      INTO v_visit, v_atoms, v_status, v_meta, v_run
      FROM (
        SELECT vn.*,
               (SELECT count(*) FROM jsonb_array_elements(COALESCE(vn.atoms,'[]'::jsonb)) a
                 WHERE a->>'svc' = ANY(p_svcs)
                   AND COALESCE(a->>'status','pending') = 'done'
                   AND (p_since IS NULL OR (a->>'done_at') IS NULL
                        OR (a->>'done_at')::timestamptz >= p_since)) AS n_reopenable,
               (SELECT count(*) FROM jsonb_array_elements(COALESCE(vn.atoms,'[]'::jsonb)) a
                 WHERE COALESCE(a->>'status','pending') NOT IN ('done','cancelled')) AS n_outstanding
          FROM ottoq_visit_needs vn
         WHERE vn.vehicle_id = p_vehicle
           AND vn.created_at >= now() - interval '24 hours' AND COALESCE(vn.sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid) = COALESCE((SELECT r0.sim_run_id FROM public.ottoq_sim_runs r0 WHERE r0.status = 'running' AND r0.depot_id = vn.depot_id ORDER BY r0.started_at DESC LIMIT 1), '00000000-0000-0000-0000-000000000000'::uuid) /* 0124 */
      ) c
     WHERE c.n_reopenable > 0 OR c.n_outstanding > 0
     ORDER BY c.n_reopenable DESC, c.n_outstanding DESC, c.created_at DESC
     LIMIT 1;
    v_fallback := (v_visit IS NOT NULL);
  END IF;

  IF v_visit IS NULL THEN RETURN 0; END IF;

  -- ══════════════ LOOP BOUND — a thrashing vehicle must terminate ══════════════
  v_max := GREATEST(COALESCE(public.ottoq_policy_get(v_run,'visit_reopen_max_attempts',3)::int, 3), 0);
  v_attempts := COALESCE((v_meta->'reopen'->>'attempts')::int, 0);
  IF v_attempts >= v_max THEN
    BEGIN
      UPDATE ottoq_visit_needs
         SET meta = COALESCE(meta,'{}'::jsonb)
                    || jsonb_build_object('reopen_escalated', true,
                                          'reopen_escalated_at', COALESCE(p_at, now()), /* 0194 */
                                          'reopen_escalated_reason', p_reason)
       WHERE visit_id = v_visit;
      PERFORM public.ottoq_record_event(
        p_actor_type := 'ottoq_engine', p_actor_id := 'reopen_visit_atoms',
        p_event_type := 'ottoq.replan_escalated',
        p_entity_type := 'vehicle', p_entity_id := p_vehicle,
        p_payload := jsonb_build_object('visit_id', v_visit, 'attempts', v_attempts,
                                        'max_attempts', v_max, 'reason', p_reason,
                                        'doctrine','bounded_replan_then_flag'),
        p_severity := 'warning', p_ingest_source := 'twin', p_data_source := 'twin',
        p_sim_run_id := v_run);
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'replan_escalated stamp dropped: sqlstate=% msg=%', SQLSTATE, SQLERRM;
    END;
    RETURN 0;
  END IF;

  -- ══════════════ PHASE 10 FIX B-2 — RE-OPEN THE ATOM, NOT JUST THE ROW ══════════════
  -- The old loop only ever touched atoms at status='done'. MEASURED (phase 9): across the
  -- whole run mechanical_pm sat at 62 pending / 2 open, sensor_calibration 24 pending / 0,
  -- fault_repair 6 pending / 0 -- a bay marks its atom done only on CLEAN EXIT, so an
  -- interrupted session almost never leaves a 'done' atom behind. That is why strict
  -- atoms_reopened>0 was 2 of 8: there was literally nothing in 'done' state to re-open.
  FOR v_a IN SELECT * FROM jsonb_array_elements(COALESCE(v_atoms,'[]'::jsonb)) LOOP
    v_st := lower(COALESCE(v_a->>'status','pending'));

    IF v_a->>'svc' = ANY(p_svcs) AND v_st <> 'cancelled' THEN
      IF v_st = 'done'
         AND (p_since IS NULL OR (v_a->>'done_at') IS NULL OR (v_a->>'done_at')::timestamptz >= p_since)
      THEN
        -- Credited, then the session was cut short: the credit is void. Redo it.
        v_a := (v_a - 'done_at')
               || jsonb_build_object('status','open', 'reopened_at', to_jsonb(COALESCE(p_at, now())), /* 0194 */
                                     'reopen_reason', p_reason, 'reopened_from', 'done');
        v_from_done := v_from_done + 1; v_n := v_n + 1;
      ELSIF v_st IN ('in_progress','active','started') THEN
        -- Visibly mid-work when the space was taken away. Genuinely cut short.
        v_a := (v_a - 'done_at')
               || jsonb_build_object('status','open', 'reopened_at', to_jsonb(COALESCE(p_at, now())), /* 0194 */
                                     'reopen_reason', p_reason, 'reopened_from', v_st);
        v_from_active := v_from_active + 1; v_n := v_n + 1;
      ELSIF v_st <> 'done' THEN
        -- ALREADY DUE. The atom was never credited, so there is nothing to re-open. Stamp it
        -- so the interruption is auditable, but do NOT count it as a re-open -- counting it
        -- would inflate the metric with work the depot never actually lost.
        v_a := v_a || jsonb_build_object('cut_short_at', to_jsonb(COALESCE(p_at, now())), /* 0194 */
                                         'cut_short_reason', p_reason);
        v_already_due := v_already_due + 1;
      END IF;
    END IF;

    IF lower(COALESCE(v_a->>'status','pending')) NOT IN ('done','cancelled') THEN
      v_outstanding := v_outstanding + 1;
    END IF;
    v_new := v_new || jsonb_build_array(v_a);
  END LOOP;

  -- Row-level stamp. `ottoq_visit_needs` has NO reopen_reason COLUMN, so the row-level
  -- telemetry the doctrine asks for lives in meta->>'reopen_reason'.
  v_stamp := jsonb_build_object(
    'reopen_reason', p_reason,
    'reopen', jsonb_build_object('attempts', v_attempts + 1,
                                 'max_attempts', v_max,
                                 'last_reason', p_reason,
                                 'last_at', COALESCE(p_at, now()), /* 0194 */
                                 'atoms_reopened', v_n,
                                 'atoms_reopened_from_done', v_from_done,
                                 'atoms_reopened_from_active', v_from_active,
                                 'atoms_already_due', v_already_due,
                                 'outstanding_restored', CASE WHEN v_n = 0 THEN v_outstanding ELSE 0 END,
                                 'via_fallback', v_fallback,
                                 'prior_status', v_status));

  -- ══════════════ PHASE 10 FIX B-1 — WRITE ALWAYS ══════════════
  -- WAS: `ELSIF v_outstanding > 0 AND v_status <> 'open' THEN`.
  -- When the needs row happened to be ALREADY open, that guard made the function write
  -- NOTHING -- no atom change, no meta stamp, no visit_reopened event -- and the caller's
  -- outcome check (`meta->>'reopen_reason' = 'bay_session_interrupted'`) therefore scored the
  -- interruption as FORGOTTEN. All 3 of the 3 phase-9 total misses were this branch
  -- (2d2c46af, ca2624fc, c3333333: none had a reopen key in meta).
  IF v_n > 0 OR v_outstanding > 0 THEN
    UPDATE ottoq_visit_needs
       SET atoms  = v_new,
           status = 'open',
           meta   = COALESCE(meta,'{}'::jsonb) || v_stamp
     WHERE visit_id = v_visit;
    v_row_reopened := true;
  END IF;

  IF v_row_reopened THEN
    BEGIN
      PERFORM public.ottoq_record_event(
        p_actor_type := 'ottoq_engine', p_actor_id := 'reopen_visit_atoms',
        p_event_type := 'ottoq.visit_reopened',
        p_entity_type := 'vehicle', p_entity_id := p_vehicle,
        p_payload := jsonb_build_object('visit_id', v_visit,
                                        'atoms_reopened', v_n,
                                        'atoms_reopened_from_done', v_from_done,
                                        'atoms_reopened_from_active', v_from_active,
                                        'atoms_already_due', v_already_due,
                                        'outstanding_restored', CASE WHEN v_n = 0 THEN v_outstanding ELSE 0 END,
                                        'outstanding_after', v_outstanding,
                                        'prior_status', v_status,
                                        'via_fallback', v_fallback,
                                        'attempts', v_attempts + 1,
                                        'max_attempts', v_max,
                                        'reopen_reason', p_reason),
        p_severity := 'warning', p_ingest_source := 'twin', p_data_source := 'twin',
        p_sim_run_id := v_run);
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'visit_reopened audit event dropped: sqlstate=% msg=%', SQLSTATE, SQLERRM;
    END;
  END IF;

  RETURN v_n;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'ottoq_reopen_visit_atoms: FAILED sqlstate=% msg=% vehicle=%', SQLSTATE, SQLERRM, p_vehicle;
  RETURN 0;
END
$function$;

CREATE OR REPLACE FUNCTION ottoq.ottoq_emit_booking_interrupted(p_sim_run_id uuid, p_depot_id uuid, p_booking_id uuid, p_vehicle_id uuid, p_stall_id uuid, p_purpose text, p_clock timestamp with time zone, p_release_reason text, p_planned_s numeric, p_actual_s numeric, p_atoms_reopened integer, p_legs_replanned integer, p_source text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_outstanding int := -1;   -- -1 == "could not be measured", never confused with a real 0
  v_remaining_min numeric;
  v_ratio numeric;
BEGIN
  -- OUTCOME CHECK: is work still DUE for this vehicle after the interruption?
  -- Its own handler: a metric read must never cost us the audit record.
  BEGIN
    SELECT count(*) INTO v_outstanding
      FROM public.ottoq_visit_needs vn
     WHERE vn.vehicle_id = p_vehicle_id
       AND vn.status = 'open'
       AND vn.meta ? 'reopen' AND COALESCE(vn.sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid) = COALESCE(p_sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid) /* 0124 */;
  EXCEPTION WHEN OTHERS THEN
    v_outstanding := -1;
    RAISE WARNING 'booking_interrupted: outstanding_restored probe failed sqlstate=% msg=% booking=%',
      SQLSTATE, SQLERRM, p_booking_id;
  END;

  v_remaining_min := CASE
      WHEN p_planned_s IS NULL OR p_actual_s IS NULL THEN NULL
      ELSE round(GREATEST(p_planned_s - p_actual_s, 0)::numeric / 60.0, 2) END;
  v_ratio := CASE
      WHEN p_planned_s IS NULL OR p_actual_s IS NULL OR p_planned_s = 0 THEN NULL
      ELSE round(p_actual_s / p_planned_s, 3) END;

  BEGIN
    PERFORM public.ottoq_record_event(
      p_actor_type    := 'ottoq_engine',
      p_actor_id      := COALESCE(p_source,'unknown'),
      p_event_type    := 'ottoq.booking_interrupted',
      p_entity_type   := 'vehicle',
      p_entity_id     := p_vehicle_id,
      p_depot_id      := p_depot_id,
      p_payload       := jsonb_build_object(
        -- identity
        'booking_id',            p_booking_id,
        'stall_id',              p_stall_id,
        'purpose',               p_purpose,
        'release_reason',        p_release_reason,
        'source',                p_source,
        -- THE CONTRACT: these four keys are present on EVERY emission, from every path.
        'atoms_reopened',        COALESCE(p_atoms_reopened, 0),
        'legs_replanned',        COALESCE(p_legs_replanned, 0),
        'outstanding_restored',  v_outstanding,
        'minutes_remaining',     v_remaining_min,
        -- supporting detail
        'planned_min',           CASE WHEN p_planned_s IS NULL THEN NULL ELSE round(p_planned_s/60.0,2) END,
        'actual_min',            CASE WHEN p_actual_s  IS NULL THEN NULL ELSE round(p_actual_s /60.0,2) END,
        'completion_ratio',      v_ratio,
        'emitter_version',       2,
        'doctrine',              'full_service_visit_is_atomic; interrupted work stays DUE and must be re-booked'),
      p_severity      := 'warning',
      p_ingest_source := 'twin',
      p_data_source   := 'twin',
      p_sim_run_id    := p_sim_run_id);
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'booking_interrupted EMISSION DROPPED sqlstate=% msg=% booking=% vehicle=% reason=% source=%',
      SQLSTATE, SQLERRM, p_booking_id, p_vehicle_id, p_release_reason, p_source;
  END;

EXCEPTION WHEN OTHERS THEN
  -- Belt and braces: nothing in here may ever abort a tick.
  RAISE WARNING 'ottoq_emit_booking_interrupted: TOTAL FAILURE sqlstate=% msg=% booking=%',
    SQLSTATE, SQLERRM, p_booking_id;
END
$function$;

CREATE OR REPLACE FUNCTION ottoq.ottoq_release_vacated_spaces(p_sim_run_id uuid, p_depot_id uuid, p_clock timestamp with time zone)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE v_n int := 0; v_m int := 0; v_grace int; v_rec record; v_reopened int;
        v_departed int := 0;   -- 0329
        v_legs int := 0; v_leg_cap int := 3; v_needs_open int := 0;
        v_activated int := 0;
BEGIN
  IF p_sim_run_id IS NULL OR p_depot_id IS NULL OR p_clock IS NULL THEN RETURN 0; END IF;

  -- (a) vehicle still POINTS at a bay it is no longer working in -> drop the pointer.
  UPDATE public.vehicles v
     SET current_stall_id = NULL
   WHERE v.home_depot_id    = p_depot_id
     AND v.current_stall_id IS NOT NULL
     AND v.current_state NOT IN ('in_wash_bay'::vehicle_state,
                                 'in_detail_bay'::vehicle_state,
                                 'in_service_bay'::vehicle_state)
     AND EXISTS (SELECT 1 FROM public.stalls s
                  WHERE s.id = v.current_stall_id
                    AND s.stall_type IN ('wash_bay'::stall_type,'service_bay'::stall_type));
  GET DIAGNOSTICS v_n = ROW_COUNT;

  -- (b) bay stalls whose occupant no longer claims them -> hard-free. Never dcfc/l2/staging.
  UPDATE public.stalls s
     SET current_vehicle_id = NULL, reserved_by = NULL,
         reservation_expires_at = NULL, status = 'available'
   WHERE s.depot_id = p_depot_id
     AND s.stall_type IN ('wash_bay'::stall_type,'service_bay'::stall_type)
     AND s.status NOT IN ('maintenance','closed')
     AND (s.current_vehicle_id IS NOT NULL OR s.reserved_by IS NOT NULL)
     AND NOT EXISTS (
           SELECT 1 FROM public.vehicles v
            WHERE v.id = COALESCE(s.current_vehicle_id, s.reserved_by)
              AND v.current_stall_id = s.id
              AND v.current_state IN ('in_wash_bay'::vehicle_state,
                                      'in_detail_bay'::vehicle_state,
                                      'in_service_bay'::vehicle_state));
  GET DIAGNOSTICS v_m = ROW_COUNT;

  v_grace   := GREATEST(public.ottoq_policy_get(p_sim_run_id,'booking_no_show_grace_min',15)::int, 0);
  v_leg_cap := GREATEST(public.ottoq_policy_get(p_sim_run_id,'leg_replan_max_attempts',3)::int, 0);

  -- ══════════ PHASE 11 (b2): KEEP THE APPOINTMENT BEFORE BURNING THE GRACE ══════════
  -- MUST run after (a)/(b) -- those free the stalls this sweep needs -- and BEFORE the
  -- grace sweep in (c), which is what was silently converting un-enacted reservations
  -- into `no_show_grace_elapsed`. The grace itself is UNCHANGED at v_grace minutes.
  -- Self-contained handler: a failure here can never cost us the release logic below.
  BEGIN
    v_activated := ottoq.ottoq_activate_due_bay_reservations(p_sim_run_id, p_depot_id, p_clock);
  EXCEPTION WHEN OTHERS THEN
    v_activated := 0;
    RAISE WARNING 'activate_due_bay_reservations FAILED sqlstate=% msg=% run=%',
      SQLSTATE, SQLERRM, p_sim_run_id;
  END;

  -- (c) CALENDAR.
  -- BUILD 2: `done` now MEANS FINISHED. A bay booking whose actual occupancy is materially
  -- shorter than its planned window closes as the terminal state `interrupted` instead.
  -- The planned window is read from b.during BEFORE the clip (RHS of an UPDATE sees OLD).
  FOR v_rec IN
    WITH cand AS (
      SELECT b.booking_id, b.state AS old_state, b.purpose,
             lower(b.during) AS lo, upper(b.during) AS hi,
             GREATEST(lower(b.during) + interval '1 second',
                      LEAST(upper(b.during), p_clock)) AS clip_hi
        FROM public.ottoq_stall_bookings b
       WHERE b.sim_run_id = p_sim_run_id
         AND b.state IN ('held','active')
         -- 'active' closes on the EXIT EVENT (the NOT EXISTS below IS that event) -- no grace,
         -- because the space is genuinely free the moment the vehicle is gone.
         -- 'held' is a forward reservation nobody has taken: only the no-show grace closes it.
         AND ( b.state = 'active'
               OR lower(b.during) + make_interval(mins => v_grace) <= p_clock )
         AND EXISTS (SELECT 1 FROM public.stalls s
                      WHERE s.id = b.stall_id AND s.depot_id = p_depot_id
                        AND s.stall_type IN ('wash_bay'::stall_type,'service_bay'::stall_type))
         AND NOT EXISTS (SELECT 1 FROM public.vehicles v
                          WHERE v.id = b.vehicle_id AND v.current_stall_id = b.stall_id
                            AND v.current_state IN ('in_wash_bay'::vehicle_state,
                                                    'in_detail_bay'::vehicle_state,
                                                    'in_service_bay'::vehicle_state))
    ), decided AS (
      SELECT c.*,
             EXTRACT(epoch FROM (c.hi - c.lo))::numeric      AS planned_s,
             EXTRACT(epoch FROM (c.clip_hi - c.lo))::numeric AS actual_s,
             CASE WHEN c.old_state = 'active' THEN
                    CASE WHEN ottoq.ottoq_booking_interrupted(
                                c.purpose,
                                EXTRACT(epoch FROM (c.hi - c.lo))::numeric,
                                EXTRACT(epoch FROM (c.clip_hi - c.lo))::numeric)
                         THEN 'interrupted' ELSE 'done' END
                  ELSE 'released' END                        AS new_state
        FROM cand c
    ), upd AS (
      UPDATE public.ottoq_stall_bookings b
         SET state          = d.new_state,
             released_at    = p_clock,
             release_reason = CASE d.new_state
                                WHEN 'interrupted' THEN 'bay_exit_before_planned_end'
                                WHEN 'done'        THEN 'bay_exit_transition'
                                ELSE                    'no_show_grace_elapsed' END,
             during         = CASE WHEN d.old_state = 'active'
                                   THEN tstzrange(d.lo, d.clip_hi, '[)')
                                   ELSE b.during END
        FROM decided d
       WHERE b.booking_id = d.booking_id
      RETURNING b.booking_id, b.vehicle_id, b.stall_id, b.purpose,
                d.lo, d.planned_s, d.actual_s, d.new_state
    )
    SELECT * FROM upd WHERE new_state = 'interrupted' ORDER BY vehicle_id, stall_id   /* 0054: run-stable order (never per-run booking UUIDs) */
  LOOP
    -- RE-PLAN. The vehicle still needs this work; the full-service visit is not complete.
    v_reopened := public.ottoq_reopen_visit_atoms(
                    v_rec.vehicle_id,
                    ottoq.ottoq_bay_purpose_atoms(v_rec.purpose),
                    v_rec.lo,
                    'bay_session_interrupted', p_clock /* 0194 */);

    -- ══════════════ FIX 1(b) — UN-STRAND THE BOUND LEG ══════════════
    v_legs := 0;
    BEGIN
      UPDATE public.ottoq_itinerary_legs l
         SET status            = 'planned',
             to_stall_id       = NULL,
             actual_start_sim  = NULL,
             actual_end_sim    = NULL,
             planned_start_sim = p_clock,
             planned_end_sim   = p_clock + make_interval(secs =>
                                   GREATEST(COALESCE(l.planned_duration_s,
                                            EXTRACT(epoch FROM (l.planned_end_sim - l.planned_start_sim))::int,
                                            1800), 60)),
             duration_basis    = COALESCE(l.duration_basis,'{}'::jsonb) || jsonb_build_object(
                                   'replan', jsonb_build_object(
                                     'reason','bay_session_interrupted',
                                     'at', p_clock,
                                     'attempts', COALESCE((l.duration_basis->'replan'->>'attempts')::int,0) + 1,
                                     'max_attempts', v_leg_cap,
                                     'booking_id', v_rec.booking_id,
                                     'prev_planned_start', l.planned_start_sim,
                                     'prev_planned_end', l.planned_end_sim,
                                     'prev_actual_start', l.actual_start_sim))
       WHERE l.sim_run_id = p_sim_run_id
         AND l.vehicle_id = v_rec.vehicle_id
         AND l.status     = 'active'
         AND l.actual_end_sim IS NULL
         AND (l.to_stall_id = v_rec.stall_id
              OR l.leg_type = ANY (ottoq.ottoq_bay_purpose_leg_types(v_rec.purpose)))
         AND COALESCE((l.duration_basis->'replan'->>'attempts')::int,0) < v_leg_cap;
      GET DIAGNOSTICS v_legs = ROW_COUNT;
    EXCEPTION WHEN OTHERS THEN
      v_legs := -1;
      RAISE WARNING 'leg un-strand FAILED sqlstate=% msg=% vehicle=%', SQLSTATE, SQLERRM, v_rec.vehicle_id;
    END;

    -- OUTCOME CHECK, not an intention check: did the vehicle actually end up with work DUE?
    BEGIN
      SELECT count(*) INTO v_needs_open
        FROM public.ottoq_visit_needs vn
       WHERE vn.vehicle_id = v_rec.vehicle_id
         AND vn.status = 'open'
         AND vn.meta->>'reopen_reason' = 'bay_session_interrupted';
    EXCEPTION WHEN OTHERS THEN v_needs_open := -1;
    END;

    -- AUDIT.
    PERFORM ottoq.ottoq_emit_booking_interrupted(
      p_sim_run_id, p_depot_id, v_rec.booking_id, v_rec.vehicle_id, v_rec.stall_id,
      v_rec.purpose, p_clock, 'bay_exit_before_planned_end',
      v_rec.planned_s, v_rec.actual_s, v_reopened, v_legs, 'release_vacated_spaces');
  END LOOP;

  -- ══════════ 0329: THE OTHER 153 STALLS ══════════
  -- Everything above this line is bay-only by design and that design is
  -- right: phases (a) and (b) hard-free physical rows. This call is
  -- calendar-only and self-contained, so a failure in it can never cost
  -- the bay logic above. Inert unless space_departure_release_enabled=1.
  BEGIN
    v_departed := ottoq.ottoq_release_departed_spaces(p_sim_run_id, p_depot_id, p_clock);
  EXCEPTION WHEN OTHERS THEN
    v_departed := 0;
    RAISE WARNING 'release_departed_spaces FAILED sqlstate=% msg=% run=%',
      SQLSTATE, SQLERRM, p_sim_run_id;
  END;

  RETURN v_n + v_m + v_activated + v_departed;

EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'ottoq_release_vacated_spaces: FAILED sqlstate=% msg=% run=% depot=%',
    SQLSTATE, SQLERRM, p_sim_run_id, p_depot_id;
  RETURN 0;
END
$function$;
